// ONEUNSIGNED parameter. The LSB (register output) is a function of the LFSR
// state, not a direct tap.
module GaloisLFSR32(input clk, input reset, output reg [31:0] q);
    reg [31:0] r;
    wire t1 = r[31] ^ r[21] ^ r[1] ^ r[0];
    wire t2 = r[31] ^ r[21] ^ r[1] ^ 1'b1;
    always @(posedge clk) begin
        if (reset) r <= 32'h1;
        else r <= {r[30:0], t1} ^ {31'b0, t2};
    end
    always @(*) q = r;
endmodule

