// the feedback combinational (no register) produces the next stage, and
// the same combinational form is re-used to go back to stage 0.
module TopModule(
    input  clk,
    input  reset,
    output reg [31:0] q
);
    reg [31:0] s1, s2, s3, s4;
    wire       fb;
    // Stage 1: TRANSPOSED, register+comb -> combinational form.
    always @(*) begin
        s1 = {q[30:0], q[31]} ^ {q[21], q[31]} ^ {q[1], q[31]} ^ {q[0], q[31]};
    // Stage 2: TRANSPOSED, one register + the combinational form
    //          stage 0 -> stage 1.
    end
    always @(*) s2 = {s1[29:0], s1[31]} ^ {s1[20], s1[31]} ^ {s1[2], s1[31]} ^ {s1[1], s1[31]};
